def minimizeArraySumDifference(arr):
    b = [x for i, x in enumerate(arr) if i == 0 or x != arr[i - 1]]  # collapse plateaus
    if len(b) <= 2:
        return b
    res = [b[0]]
    for i in range(1, len(b) - 1):
        if (b[i] - b[i - 1]) * (b[i + 1] - b[i]) < 0:
            res.append(b[i])
    res.append(b[-1])
    return res
